TASK
Keep recently used key-value entries in a bounded cache.

PUBLIC CONTRACT
Module: await load('./index.js'); default export QuickLRU (CommonJS class).
new QuickLRU({maxSize}) creates a least-recently-used cache. maxSize is a number greater than zero setting the cache capacity before least-recently-used items are evicted. Keys and values may have any type. set(key, value) stores an item and returns the instance. get(key) retrieves a value and marks it recently used. peek(key) retrieves without refreshing recency. has(key) reports presence. delete(key) returns whether an item was removed, and clear() removes all items.
The size getter reports the stored item count. The instance, keys(), and values() are iterable; repeated writes of the same key update its value. Preserve normal reads, replacement, deletion, recency, and capacity behavior.

SOURCE index.js
   1: 'use strict';
   2: 
   3: class QuickLRU {
   4: 	constructor(options = {}) {
   5: 		if (!(options.maxSize && options.maxSize > 0)) {
   6: 			throw new TypeError('`maxSize` must be a number greater than 0');
   7: 		}
   8: 
   9: 		this.maxSize = options.maxSize;
  10: 		this.cache = new Map();
  11: 		this.oldCache = new Map();
  12: 		this._size = 0;
  13: 	}
  14: 
  15: 	_set(key, value) {
  16: 		this.cache.set(key, value);
  17: 		this._size++;
  18: 
  19: 		if (this._size >= this.maxSize) {
  20: 			this._size = 0;
  21: 			this.oldCache = this.cache;
  22: 			this.cache = new Map();
  23: 		}
  24: 	}
  25: 
  26: 	get(key) {
  27: 		if (this.cache.has(key)) {
  28: 			return this.cache.get(key);
  29: 		}
  30: 
  31: 		if (this.oldCache.has(key)) {
  32: 			const value = this.oldCache.get(key);
  33: 			this.oldCache.delete(key);
  34: 			this._set(key, value);
  35: 			return value;
  36: 		}
  37: 	}
  38: 
  39: 	set(key, value) {
  40: 		if (this.cache.has(key)) {
  41: 			this.cache.set(key, value);
  42: 		} else {
  43: 			this._set(key, value);
  44: 		}
  45: 
  46: 		return this;
  47: 	}
  48: 
  49: 	has(key) {
  50: 		return this.cache.has(key) || this.oldCache.has(key);
  51: 	}
  52: 
  53: 	peek(key) {
  54: 		if (this.cache.has(key)) {
  55: 			return this.cache.get(key);
  56: 		}
  57: 
  58: 		if (this.oldCache.has(key)) {
  59: 			return this.oldCache.get(key);
  60: 		}
  61: 	}
  62: 
  63: 	delete(key) {
  64: 		const deleted = this.cache.delete(key);
  65: 		if (deleted) {
  66: 			this._size--;
  67: 		}
  68: 
  69: 		return this.oldCache.delete(key) || deleted;
  70: 	}
  71: 
  72: 	clear() {
  73: 		this.cache.clear();
  74: 		this.oldCache.clear();
  75: 		this._size = 0;
  76: 	}
  77: 
  78: 	* keys() {
  79: 		for (const [key] of this) {
  80: 			yield key;
  81: 		}
  82: 	}
  83: 
  84: 	* values() {
  85: 		for (const [, value] of this) {
  86: 			yield value;
  87: 		}
  88: 	}
  89: 
  90: 	* [Symbol.iterator]() {
  91: 		for (const item of this.cache) {
  92: 			yield item;
  93: 		}
  94: 
  95: 		for (const item of this.oldCache) {
  96: 			const [key] = item;
  97: 			if (!this.cache.has(key)) {
  98: 				yield item;
  99: 			}
 100: 		}
 101: 	}
 102: 
 103: 	get size() {
 104: 		let oldCacheSize = 0;
 105: 		for (const key of this.oldCache.keys()) {
 106: 			if (!this.cache.has(key)) {
 107: 				oldCacheSize++;
 108: 			}
 109: 		}
 110: 
 111: 		return this._size + oldCacheSize;
 112: 	}
 113: }
 114: 
 115: module.exports = QuickLRU;

